import * as Store from './store.js';
import {escapeHTML as E,todayISO,shortDate,workspaceDialog,readJSON,downloadFile,csvText,textTags,safeWebURL,rollbackWorkspaceValue} from './workspace-ui.js?v=20261124-studio-2';
import {FAVORITES_STUDIO_KEY,FAVORITE_STAGES,favoriteKey,normalizeFavoriteMeta,normalizeFavoritesStudio,normalizeFavoriteFilters,inCollection,filterFavoriteRecords,validateFavoriteImport,teamReadiness,ROTATION_ACTIONS,normalizeRotation,rotationTimeline} from './favorites-studio-model.js?v=20261124-studio-2';
import {PLANNING_KEY,normalizePlanning} from './planning-studio-model.js?v=20261124-studio-2';
const UI_KEY='astralis:favorites-studio-ui:v1',games={gi:'Genshin',hsr:'Star Rail',ww:'Wuthering Waves'},cats={character:'Personnages',weapon:'Armes',artifact:'Sets',material:'Objets',team:'Équipes',news:'Lectures',farm:'Farm'};
let context={},ui=normalizeFavoriteFilters(readJSON(UI_KEY,{})),selection=new Set(),comparison=[],undo=[],spotlight='';
const data=()=>{try{return normalizeFavoritesStudio(readJSON(FAVORITES_STUDIO_KEY,{}));}catch{return normalizeFavoritesStudio({});}};
const records=()=>context.records||[];
const metadata=r=>normalizeFavoriteMeta(data().items[favoriteKey(r)]);
function save(d){localStorage.setItem(FAVORITES_STUDIO_KEY,JSON.stringify(normalizeFavoritesStudio(d)));}
function captureUndo(){return {data:data(),favs:Store.favorites(),teams:Object.fromEntries(Object.keys(games).map(g=>[g,Store.teams(g)])),tasks:Store.allTasks(),planner:normalizePlanning(readJSON(PLANNING_KEY,{})),owned:Object.fromEntries(Object.keys(games).map(g=>[g,Store.ownedMap(g)]))};}
function remember(){undo.push(captureUndo());undo=undo.slice(-20);}
function sealUndo(force=false){const last=undo.at(-1);if(last&&(!last.after||force))last.after=captureUndo();}
function change(fn,label,recordUndo=true){if(recordUndo)remember();const d=data();fn(d);if(label)d.activity.push({at:Date.now(),label});save(d);refresh();}
function refresh(){sealUndo();localStorage.setItem(UI_KEY,JSON.stringify(ui));context.refresh?.();}
function updateMeta(key,patch,label){change(d=>{d.items[key]={...normalizeFavoriteMeta(d.items[key]),...patch,updated:Date.now()};},label);}
const byKey=key=>records().find(r=>favoriteKey(r)===key);
const thumb=r=>r?.image||r?.images?.[0]||'';
function media(r,cls=''){const src=thumb(r);return src?`<img class="${cls}" src="${E(src)}" alt="${E(r.name)}" loading="lazy" decoding="async">`:`<span class="fs-missing-image ${cls}">${E(r?.name?.slice(0,1)||'?')}</span>`;}
function galleryCard(r,index){const key=favoriteKey(r),m=metadata(r);return `<article class="ws-card fs-card" style="--card-index:${index%10}" draggable="true" data-fs-drag="${E(key)}"><div class="fs-card-actions"><label><input type="checkbox" data-fs-select="${E(key)}" ${selection.has(key)?'checked':''} aria-label="Sélectionner ${E(r.name)}"></label><span class="ws-kicker">${E(games[r.game])} · ${E(cats[r.category]||r.category)}</span><button type="button" data-fs-pin="${E(key)}" aria-pressed="${m.pinned}" aria-label="Épingler ${E(r.name)}">${m.pinned?'◆':'◇'}</button></div>${r.category==='character'&&r.legacyCardHTML?`<div class="fs-original-character">${r.legacyCardHTML}</div>`:`<button type="button" class="fs-cover" data-fs-open="${E(key)}">${r.splash?`<img class="ws-cover" src="${E(r.splash)}" alt="${E(r.name)}" loading="lazy">`:media(r,'ws-cover')}</button><div class="fs-card-copy"><small>${E(r.subtitle||r.facet||'')}</small><h3><button type="button" data-fs-open="${E(key)}">${E(r.name)}</button></h3></div>`}<div class="fs-card-meta"><div><span class="ws-badge">${E(FAVORITE_STAGES.find(([id])=>id===m.stage)?.[1])}</span><span class="fs-rating" aria-label="${m.rating} sur 5">${'★'.repeat(m.rating)}${'☆'.repeat(5-m.rating)}</span></div>${m.notes?`<p>${E(m.notes.slice(0,110))}${m.notes.length>110?'…':''}</p>`:'<p class="ws-muted">Une idée à garder, un projet à construire.</p>'}${m.target?`<progress value="${m.have}" max="${m.target}" aria-label="Objectif de collection"></progress><small>${m.have} / ${m.target} · ${Math.max(0,m.target-m.have)} restant(s)</small>`:''}${m.checklist.length?`<small>${m.checklist.filter(s=>s.done).length} / ${m.checklist.length} étapes validées</small>`:''}${m.due?`<small class="${m.due<todayISO()?'ws-warning':''}">À revoir le ${shortDate(m.due)}</small>`:''}<div class="ws-tags">${m.tags.slice(0,4).map(t=>`<span>#${E(t)}</span>`).join('')}</div><footer><button type="button" data-fs-edit="${E(key)}">Mon carnet</button><button type="button" data-fs-compare="${E(key)}" aria-pressed="${comparison.includes(key)}">Comparer</button></footer></div></article>`;}
function compactCard(r){const key=favoriteKey(r),m=metadata(r);return `<article class="fs-board-card" draggable="true" data-fs-drag="${E(key)}">${media(r)}<div><button type="button" data-fs-edit="${E(key)}">${E(r.name)}</button><small>${E(cats[r.category])} · ${E(games[r.game])}</small>${m.checklist.length?`<small>${m.checklist.filter(s=>s.done).length}/${m.checklist.length} étapes</small>`:''}</div><label><input type="checkbox" data-fs-select="${E(key)}" ${selection.has(key)?'checked':''} aria-label="Sélectionner ${E(r.name)}"></label></article>`;}
export function renderFavoritesStudio(ctx){
 context=ctx;const d=data(),visible=filterFavoriteRecords(records(),d,ui),all=records().filter(r=>!metadata(r).archived),current=d.collections.find(c=>c.id===ui.collection),tags=[...new Set(Object.values(d.items).flatMap(m=>m.tags))],pinned=all.filter(r=>metadata(r).pinned);selection=new Set([...selection].filter(k=>byKey(k)));comparison=comparison.filter(k=>byKey(k));
 return `<section class="ws-workspace favorites-studio" data-favorites-studio><header class="ws-page-head"><div><span class="ws-kicker">LES ARCHIVES DE TES ENVIES</span><h1>Garder l’inspiration.<br><em>Lui donner une suite.</em></h1><p>Une bibliothèque personnelle pour réunir tes personnages, composer des équipes et faire grandir tes projets.</p></div><div class="ws-head-actions"><button type="button" data-fs-action="team">Composer une équipe</button><button type="button" class="ws-primary" data-fs-action="collection">+ Une collection</button></div></header>
 <div class="fs-collection-strip"><button type="button" data-fs-collection="all" aria-pressed="${ui.collection==='all'}"><span class="fs-collection-mark">✧</span><strong>Tout ce que tu gardes</strong><small>${all.length} favoris · ${d.collections.length} collections</small></button>${d.collections.map(c=>`<button type="button" data-fs-collection="${E(c.id)}" data-fs-collection-drop="${E(c.id)}" style="--collection-color:${E(c.color)}" aria-pressed="${ui.collection===c.id}"><span class="fs-collection-mark">${c.smart?'⌘':'◇'}</span><strong>${E(c.name)}</strong><small>${all.filter(r=>inCollection(r,c,d.items[favoriteKey(r)])).length} éléments · ${c.smart?'automatique':'personnelle'}</small></button>`).join('')}</div>
 ${current?`<div class="fs-collection-caption"><div><h2>${E(current.name)}</h2><p>${E(current.description||'Un espace pour relier tes idées.')}</p></div><button type="button" data-fs-collection-edit="${E(current.id)}">Modifier la collection</button><button type="button" data-fs-collection-copy="${E(current.id)}">Dupliquer</button></div>`:''}
 <div class="ws-toolbar"><nav class="ws-view-tabs" aria-label="Vues des favoris">${[['gallery','Galerie'],['board','Progression'],['goals','Objectifs'],['teams','Équipes'],['equipment','Préparation'],['journal','Journal']].map(([id,n])=>`<button type="button" data-fs-view="${id}" aria-pressed="${ui.view===id}">${n}</button>`).join('')}</nav><div class="ws-toolbar-actions"><button type="button" data-fs-action="discover">Une idée au hasard</button><button type="button" data-fs-action="saved-view">Garder cette vue</button><button type="button" data-fs-action="tools">Partager & sauvegarder</button></div></div>
 <div class="ws-filterbar"><input type="search" data-fs-filter="query" placeholder="Un personnage, une note, une envie…" value="${E(ui.query)}" aria-label="Rechercher dans les favoris"><select data-fs-filter="game" aria-label="Univers"><option value="all">Tous les univers</option>${Object.entries(games).map(([id,n])=>`<option value="${id}" ${ui.game===id?'selected':''}>${n}</option>`).join('')}</select><select data-fs-filter="category" aria-label="Type de favori"><option value="all">Toutes les catégories</option>${Object.entries(cats).map(([id,n])=>`<option value="${id}" ${ui.category===id?'selected':''}>${n}</option>`).join('')}</select><select data-fs-filter="tag" aria-label="Étiquette"><option value="all">Toutes les étiquettes</option>${tags.map(t=>`<option ${ui.tag===t?'selected':''}>${E(t)}</option>`).join('')}</select><select data-fs-filter="sort" aria-label="Ordre des favoris">${[['manual','Mon ordre'],['name','Alphabétique'],['rating','Mes préférés'],['recent','Dernière annotation'],['progress','Progression']].map(([id,n])=>`<option value="${id}" ${ui.sort===id?'selected':''}>${n}</option>`).join('')}</select></div>
 <div class="fs-secondary-filters"><label><input type="checkbox" data-fs-flag="pinned" ${ui.pinned?'checked':''}>Épinglés seulement (${pinned.length})</label><label><input type="checkbox" data-fs-flag="archive" ${ui.archive?'checked':''}>Voir les archives</label><button type="button" data-fs-action="select-all">Sélectionner les ${visible.length} éléments</button>${d.views.map(v=>`<span class="ws-saved-views"><button type="button" data-fs-saved-view="${E(v.id)}">${E(v.name)}</button><button type="button" data-fs-delete-view="${E(v.id)}" aria-label="Supprimer la vue ${E(v.name)}">×</button></span>`).join('')}</div>
 ${selection.size?`<div class="ws-bulk"><strong>${selection.size} sélectionné(s)</strong><button type="button" data-fs-action="batch">Organiser</button><button type="button" data-fs-action="project">Créer un projet</button><button type="button" data-fs-action="clear-selection">Désélectionner</button></div>`:''}
 ${comparison.length?`<div class="fs-comparison-tray"><div>${comparison.map(k=>{const r=byKey(k);return `<button type="button" data-fs-compare="${E(k)}">${media(r)}<span>${E(r.name)}</span> ×</button>`;}).join('')}</div><button type="button" class="ws-primary" data-fs-action="compare">Comparer ${comparison.length} fiches</button></div>`:''}
 ${spotlight&&byKey(spotlight)?renderSpotlight(byKey(spotlight)):''}
 ${ui.view==='gallery'?`<div class="ws-section-head"><span>${visible.length} favoris · glisse pour réordonner ou déposer dans une collection</span><button type="button" data-nav="characters">Explorer le catalogue →</button></div><div class="fs-gallery">${visible.slice(0,Number(ui.limit)||48).map(galleryCard).join('')||empty()}</div>${visible.length>(Number(ui.limit)||48)?`<div class="ws-load-more"><span>${Number(ui.limit)||48} / ${visible.length} favoris</span><button type="button" data-fs-action="load-more">Afficher les suivants</button></div>`:''}`:ui.view==='board'?renderBoard(visible):ui.view==='goals'?renderGoals(visible):ui.view==='teams'?renderTeams():ui.view==='equipment'?renderEquipment():renderJournal(d)}
 <footer class="ws-page-footer"><span>Tes favoris restent partagés avec les catalogues. Tes notes et collections restent sur cet appareil.</span><button type="button" data-fs-action="undo" ${!undo.length?'disabled':''}>Annuler la dernière action</button></footer></section>`;
}
function empty(){return '<div class="ws-empty"><span class="ws-empty-orbit" aria-hidden="true"></span><h3>Laisse une place à tes envies.</h3><p>Ajoute un cœur depuis les catalogues ou ajuste tes filtres pour retrouver tes favoris.</p><button type="button" data-nav="characters">Explorer les personnages</button><button type="button" data-fs-action="reset-filters">Effacer les filtres</button></div>';}
function renderSpotlight(r){const m=metadata(r);return `<article class="fs-spotlight"><div>${r.splash?`<img src="${E(r.splash)}" alt="${E(r.name)}">`:media(r)}</div><section><span class="ws-kicker">UNE PISTE À EXPLORER</span><h2>${E(r.name)}</h2><p>${E(m.notes||r.description||'Une nouvelle idée pour ton prochain projet.').slice(0,450)}</p><div class="ws-inline"><button type="button" class="ws-primary" data-fs-edit="${E(favoriteKey(r))}">Ouvrir mon carnet</button><button type="button" data-fs-action="dismiss-spotlight">Fermer</button></div></section></article>`;}
function renderBoard(visible){return `<div class="ws-section-head"><h2>De l’idée à l’équipe prête.</h2><small>Chaque fiche avance à ton rythme. Glisse-la entre les colonnes.</small></div><div class="fs-board">${FAVORITE_STAGES.map(([id,n])=>`<section data-fs-stage-drop="${id}"><header><h3>${n}</h3><span>${visible.filter(r=>metadata(r).stage===id).length}</span></header>${visible.filter(r=>metadata(r).stage===id).map(compactCard).join('')}</section>`).join('')}</div>`;}
function renderGoals(visible){const withGoals=visible.filter(r=>{const m=metadata(r);return m.target||m.checklist.length||m.due;});return `<div class="ws-section-head"><div><h2>Les petites étapes d’une grande envie.</h2><p>Stocks, équipement, essais et dates à revoir : ton carnet suit ce qui est utile pour toi.</p></div><button type="button" data-fs-action="reminders">Envoyer les rappels au planificateur</button></div><div class="ws-grid">${withGoals.map(r=>{const key=favoriteKey(r),m=metadata(r);return `<article class="ws-card fs-goal"><header>${media(r)}<div><h3>${E(r.name)}</h3><small>${E(games[r.game])}</small></div><button type="button" data-fs-edit="${E(key)}">Modifier</button></header>${m.target?`<label>Quantité acquise<input type="number" data-fs-have="${E(key)}" min="0" max="1000000000" value="${m.have}"> / ${m.target}</label><progress value="${m.have}" max="${m.target}" aria-label="Progression"></progress>`:''}<div class="ws-check-list">${m.checklist.map(s=>`<label><input type="checkbox" data-fs-check="${E(key)}" data-step="${E(s.id)}" ${s.done?'checked':''}>${E(s.title)}</label>`).join('')}</div>${m.due?`<p>À revoir le ${shortDate(m.due)}</p>`:''}</article>`;}).join('')||'<div class="ws-empty"><h3>Un objectif commence dans un carnet.</h3><p>Ouvre « Mon carnet » sous une fiche pour définir une quantité, une date et des étapes.</p></div>'}</div>`;}
function renderTeams(){const teams=Object.keys(games).flatMap(g=>Store.teams(g).filter(t=>t.favorite).map(t=>({...t,game:g})));return `<div class="ws-section-head"><div><h2>Quatre places, une intention.</h2><p>Compose et enregistre des équipes avec une arme et un set par membre.</p></div><button type="button" class="ws-primary" data-fs-action="team">+ Une équipe</button></div><div class="ws-grid">${teams.map(t=>`<article class="ws-card fs-team"><span class="ws-kicker">${E(games[t.game])}</span><h3>${E(t.name)}</h3><div class="fs-team-roster">${(t.members||[]).map(m=>{const r=(context.catalog||[]).find(r=>r.game===t.game&&r.category==='character'&&String(r.rawId||r.id)===String(m.character));return `<div>${r?media(r):'<span>?</span>'}<small>${E(r?.name||'Place libre')}</small></div>`;}).join('')}</div><footer><button type="button" data-fs-team-edit="${E(t.id)}" data-fs-game="${t.game}">Modifier l’équipe</button><button type="button" data-fs-team-project="${E(t.id)}" data-fs-game="${t.game}">Plan de préparation</button></footer></article>`).join('')||'<div class="ws-empty"><h3>Une équipe à imaginer.</h3><p>Le brouillon est enregistré automatiquement, même avant de sauvegarder une équipe.</p></div>'}</div>`;}
function renderEquipment(){const catalog=context.catalog||[],teams=Object.keys(games).flatMap(game=>Store.teams(game).filter(t=>t.favorite).map(t=>({...t,game})));return `<div class="ws-section-head"><div><h2>De l’équipe imaginée à l’équipe équipée.</h2><p>La possession vient du catalogue. Les cases « Obtenu » y sont partagées, les objectifs créés ne sont pas dupliqués.</p></div></div><div class="ws-grid">${teams.map(team=>{const refs=(team.members||[]).flatMap(m=>[['character',m.character],['weapon',m.weapon],['artifact',m.set]]).filter(([,id])=>id).map(([category,id])=>catalog.find(r=>r.game===team.game&&r.category===category&&String(r.rawId)===String(id))).filter(Boolean),unique=[...new Map(refs.map(r=>[favoriteKey(r),r])).values()],owned=unique.filter(r=>Store.isOwned(r.game,r.rawId)).length;return `<article class="ws-card"><span class="ws-kicker">${E(games[team.game])}</span><h3>${E(team.name)}</h3><progress value="${owned}" max="${Math.max(1,unique.length)}" aria-label="Équipement obtenu"></progress><small>${owned}/${unique.length} références obtenues · ${rotationTimeline(team.rotation).length} actions dans la rotation</small><div class="fs-gear-list">${unique.map(r=>`<label>${media(r)}<span>${E(r.name)}<small>${E(cats[r.category])}</small></span><input type="checkbox" data-fs-gear-owned="${E(favoriteKey(r))}" ${Store.isOwned(r.game,r.rawId)?'checked':''} aria-label="${E(r.name)} obtenu"></label>`).join('')}</div><button type="button" data-fs-missing-plan="${E(team.id)}" data-fs-game="${team.game}">Planifier les références manquantes</button></article>`;}).join('')||'<div class="ws-empty"><h3>Commence par composer une équipe.</h3><p>Sa liste de personnages, armes et sets à obtenir apparaîtra ici.</p><button type="button" data-fs-action="team">Composer une équipe</button></div>'}</div>`;}
function planMissing(team,game){remember();const catalog=context.catalog||[],all=Store.allTasks(),refs=(team.members||[]).flatMap(m=>[['character',m.character],['weapon',m.weapon],['artifact',m.set]]).filter(([,id])=>id).map(([category,id])=>catalog.find(r=>r.game===game&&r.category===category&&String(r.rawId)===String(id))).filter(Boolean),unique=[...new Map(refs.map(r=>[favoriteKey(r),r])).values()],rows=unique.filter(r=>!Store.isOwned(game,r.rawId)&&!all.some(t=>t.equipmentReference===favoriteKey(r)&&!t.done)).map(r=>({id:crypto.randomUUID(),game,title:`Obtenir ${r.name}`,equipmentReference:favoriteKey(r),source:'favorites-studio',category:'collection',done:false,durationMinutes:30,priority:'Normale',notes:`Préparation de l’équipe ${team.name}`}));Store.applyTaskChanges(rows);change(d=>{d.activity.push({at:Date.now(),label:`Équipement planifié : ${team.name} · ${rows.length} objectifs`});},'',false);context.toast?.(`${rows.length} objectifs ajoutés, sans doublon.`);}
function renderJournal(d){return `<div class="ws-section-head"><h2>Le fil de tes idées.</h2><small>Annotations, collections, comparaisons et équipes</small></div><section class="ws-panel ps-history">${d.activity.slice(-50).reverse().map(a=>`<p><time>${new Date(a.at).toLocaleString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time><span>${E(a.label)}</span></p>`).join('')||'<p>Les prochaines actions apparaîtront ici.</p>'}</section>`;}
function collectionEditor(collection=null){const c=collection||{id:crypto.randomUUID(),name:'',color:'#a9bce1'},rule=c.smart||{};const d=workspaceDialog({title:collection?'Modifier la collection':'Une nouvelle collection',body:`<div class="ws-form-grid"><label class="ws-full">Nom<input name="name" value="${E(c.name)}" required maxlength="80"></label><label class="ws-full">Intention<textarea name="description" rows="3" maxlength="3000">${E(c.description||'')}</textarea></label><label>Couleur<input type="color" name="color" value="${E(c.color)}"></label><label class="ws-check"><input type="checkbox" name="smart" ${c.smart?'checked':''}>Collection automatique</label><fieldset class="ws-full"><legend>Règles de la collection automatique</legend><div class="ws-form-grid"><label>Univers<select name="game"><option value="all">Tous</option>${Object.entries(games).map(([id,n])=>`<option value="${id}" ${rule.game===id?'selected':''}>${n}</option>`).join('')}</select></label><label>Catégorie<select name="category"><option value="all">Toutes</option>${Object.entries(cats).map(([id,n])=>`<option value="${id}" ${rule.category===id?'selected':''}>${n}</option>`).join('')}</select></label><label>Étiquette<input name="tag" value="${E(rule.tag||'')}"></label><label>Progression<select name="stage"><option value="all">Toutes</option>${FAVORITE_STAGES.map(([id,n])=>`<option value="${id}" ${rule.stage===id?'selected':''}>${n}</option>`).join('')}</select></label><label>Note minimale<input type="number" name="minRating" min="0" max="5" value="${rule.minRating||0}"></label><label>Possession<select name="owned"><option value="all">Indifférente</option><option value="yes" ${rule.owned==='yes'?'selected':''}>Obtenu</option><option value="no" ${rule.owned==='no'?'selected':''}>À obtenir</option></select></label></div></fieldset></div>${collection?'<button type="button" data-fs-delete-collection class="ws-danger">Supprimer cette collection</button>':''}`,onSubmit:f=>{const row={id:c.id,name:f.get('name').trim(),description:f.get('description'),color:f.get('color'),smart:f.has('smart')?{game:f.get('game'),category:f.get('category'),stage:f.get('stage'),tag:f.get('tag').trim(),minRating:Number(f.get('minRating')),owned:f.get('owned')}:null};if(!row.name)throw Error('Donne un nom à la collection.');change(d=>{d.collections=[...d.collections.filter(x=>x.id!==c.id),row];},`Collection : ${row.name}`);ui.collection=c.id;refresh();}});d.querySelector('[data-fs-delete-collection]')?.addEventListener('click',()=>{change(d=>{d.collections=d.collections.filter(x=>x.id!==c.id);Object.values(d.items).forEach(m=>m.collections=m.collections.filter(id=>id!==c.id));},`Collection supprimée : ${c.name}`);ui.collection='all';d.close();refresh();});}
function noteEditor(r){if(!r)return;const key=favoriteKey(r),m=metadata(r),d=data();const dialog=workspaceDialog({title:`Mon carnet · ${r.name}`,wide:true,body:`<div class="fs-note-intro">${media(r)}<p>${E(r.subtitle||r.facet||cats[r.category])} · ${E(games[r.game])}<br>Les annotations sont privées sur cet appareil.</p></div><div class="ws-form-grid"><label>Progression<select name="stage">${FAVORITE_STAGES.map(([id,n])=>`<option value="${id}" ${m.stage===id?'selected':''}>${n}</option>`).join('')}</select></label><label>Mon intérêt<select name="rating">${Array.from({length:6},(_,i)=>`<option value="${i}" ${m.rating===i?'selected':''}>${i?`${i} / 5`:'Non noté'}</option>`).join('')}</select></label><label class="ws-full">Mes idées, mes essais<textarea rows="6" name="notes" maxlength="12000">${E(m.notes)}</textarea></label><label class="ws-full">Étiquettes séparées par des virgules<input name="tags" value="${E(m.tags.join(', '))}"></label><label>Quantité ou objectif à atteindre<input type="number" name="target" min="0" max="1000000000" value="${m.target}"></label><label>Quantité déjà acquise<input type="number" name="have" min="0" max="1000000000" value="${m.have}"></label><label>À revoir le<input type="date" name="due" value="${E(m.due)}"></label><label>Lien de référence<input type="url" name="link" value="${E(m.link)}" placeholder="https://…"></label><label class="ws-full">Étapes · une par ligne, [x] pour cocher<textarea rows="4" name="checklist">${E(m.checklist.map(s=>`${s.done?'[x] ':''}${s.title}`).join('\n'))}</textarea></label><fieldset class="ws-full"><legend>Dans mes collections</legend><div class="ws-check-list">${d.collections.filter(c=>!c.smart).map(c=>`<label><input type="checkbox" name="collections" value="${E(c.id)}" ${m.collections.includes(c.id)?'checked':''}>${E(c.name)}</label>`).join('')||'<p>Crée une collection pour regrouper cette fiche.</p>'}</div></fieldset><label class="ws-check"><input type="checkbox" name="pinned" ${m.pinned?'checked':''}>Épingler</label><label class="ws-check"><input type="checkbox" name="archived" ${m.archived?'checked':''}>Archiver sans retirer le cœur</label></div><div class="ws-inline"><button type="button" data-fs-note-open>Ouvrir la fiche du jeu</button><button type="button" data-fs-note-plan>Créer un objectif</button><button type="button" data-fs-note-remove class="ws-danger">Retirer des favoris</button></div>`,onSubmit:f=>{const patch={...Object.fromEntries(f),rating:Number(f.get('rating')),tags:textTags(f.get('tags')),collections:f.getAll('collections'),pinned:f.has('pinned'),archived:f.has('archived'),checklist:String(f.get('checklist')).split('\n').map(line=>{const done=/^\[x\]\s*/i.test(line),title=line.replace(/^\[x\]\s*/i,'').trim(),old=m.checklist.find(s=>s.title===title);return {id:old?.id||crypto.randomUUID(),title,done};}).filter(s=>s.title),link:f.get('link')?safeWebURL(f.get('link')):''};updateMeta(key,patch,`Carnet mis à jour : ${r.name}`);}});
 dialog.querySelector('[data-fs-note-open]').addEventListener('click',()=>{dialog.close();context.open?.(r);});dialog.querySelector('[data-fs-note-plan]').addEventListener('click',()=>{dialog.close();projectDialog([r]);});dialog.querySelector('[data-fs-note-remove]').addEventListener('click',()=>{if(r.category==='farm'){updateMeta(key,{archived:true},`Suivi masqué : ${r.name}`);dialog.close();return;}remember();context.remove?.(r);const d=data();d.activity.push({at:Date.now(),label:`Retiré des favoris : ${r.name}`});save(d);dialog.close();refresh();});}
function comparisonDialog(){const list=comparison.map(byKey).filter(Boolean);workspaceDialog({title:'Tes fiches côte à côte',wide:true,submit:null,body:`<p>Les statistiques ci-dessous viennent du catalogue. Elles ne représentent pas un build équipé.</p><div class="fs-compare-grid" style="--compare-columns:${list.length}">${list.map(r=>{const m=metadata(r);return `<article>${media(r)}<h3>${E(r.name)}</h3><dl><dt>Univers</dt><dd>${E(games[r.game])}</dd><dt>Type</dt><dd>${E(cats[r.category])}</dd><dt>Rareté</dt><dd>${r.rarity?`${r.rarity} étoiles`:'Non renseignée'}</dd><dt>Élément / catégorie</dt><dd>${E(r.facet||r.element||'—')}</dd><dt>Arme / voie</dt><dd>${E(r.weapon||r.extra||'—')}</dd><dt>Statistique secondaire</dt><dd>${E(r.secondary||'—')}</dd><dt>ATQ de base (niveau 1)</dt><dd>${E(r.baseAttack||'—')}</dd><dt>Mon intérêt</dt><dd>${m.rating}/5</dd><dt>État</dt><dd>${E(FAVORITE_STAGES.find(([id])=>id===m.stage)?.[1])}</dd></dl>${(r.effects||[]).map(effect=>`<p><strong>${E(effect.pieces?`${effect.pieces} pièces`:'Effet')}</strong><br>${E(effect.text)}</p>`).join('')}<p>${E(r.description||'Pas de description dans ce catalogue.')}</p>${m.notes?`<blockquote>${E(m.notes)}</blockquote>`:''}</article>`;}).join('')}</div>`});change(d=>{d.activity.push({at:Date.now(),label:`Comparaison : ${list.map(r=>r.name).join(', ')}`});});}
function batchDialog(){const keys=[...selection],d=data();workspaceDialog({title:`Organiser ${keys.length} favoris`,body:`<div class="ws-form-grid"><label>Action<select name="action"><option value="collection">Ajouter à une collection</option><option value="stage">Changer la progression</option><option value="tag">Ajouter des étiquettes</option><option value="pin">Épingler</option><option value="unpin">Désépingler</option><option value="archive">Archiver</option><option value="restore">Restaurer</option></select></label><label>Collection<select name="collection">${d.collections.filter(c=>!c.smart).map(c=>`<option value="${E(c.id)}">${E(c.name)}</option>`).join('')}</select></label><label>Progression<select name="stage">${FAVORITE_STAGES.map(([id,n])=>`<option value="${id}">${n}</option>`).join('')}</select></label><label>Étiquettes<input name="tags"></label></div>`,onSubmit:f=>{const action=f.get('action');if(action==='collection'&&!f.get('collection'))throw Error('Crée d’abord une collection personnelle.');change(d=>{for(const k of keys){const m=normalizeFavoriteMeta(d.items[k]);if(action==='collection')m.collections=[...new Set([...m.collections,f.get('collection')])];if(action==='stage')m.stage=f.get('stage');if(action==='tag')m.tags=[...new Set([...m.tags,...textTags(f.get('tags'))])];if(action==='pin'||action==='unpin')m.pinned=action==='pin';if(action==='archive'||action==='restore')m.archived=action==='archive';m.updated=Date.now();d.items[k]=m;}},`${keys.length} favoris organisés.`);selection.clear();refresh();}});}
function projectDialog(list){const d=workspaceDialog({title:'Transformer les envies en projet',body:`<div class="ws-form-grid"><label class="ws-full">Nom du projet<input name="name" value="${E(data().collections.find(c=>c.id===ui.collection)?.name||'Préparer mes favoris')}" required maxlength="100"></label><label>Première date<input type="date" name="due" value="${todayISO()}"></label><label>Durée par objectif (min)<input name="duration" type="number" min="5" max="240" value="30"></label><label class="ws-check ws-full"><input type="checkbox" name="steps" checked>Reprendre les étapes des carnets</label></div><ul>${list.map(r=>`<li>${E(r.name)}</li>`).join('')}</ul>`,submit:'Créer dans le planificateur',onSubmit:f=>{remember();const p={id:crypto.randomUUID(),name:f.get('name').trim(),color:'#a9bce1',game:ui.game},c=normalizePlanning(readJSON(PLANNING_KEY,{}));c.projects.push(p);localStorage.setItem(PLANNING_KEY,JSON.stringify(c));const rows=list.map(r=>({id:crypto.randomUUID(),game:r.game,title:`Préparer ${r.name}`,category:'progression',done:false,source:'favorites-studio',favoriteKey:favoriteKey(r),character:r.category==='character'?r.rawId||r.id:undefined,characterName:r.category==='character'?r.name:undefined,projectId:p.id,due:f.get('due'),durationMinutes:Number(f.get('duration')),priority:'Normale',notes:[metadata(r).notes,r.rotationNote||''].filter(Boolean).join('\n\n'),steps:[...(f.has('steps')?metadata(r).checklist.map(s=>({...s})):[]),...(r.preparationSteps||[])]}));Store.applyTaskChanges(rows);change(d=>{d.activity.push({at:Date.now(),label:`Projet créé : ${p.name} · ${rows.length} objectifs`});},'',false);context.toast?.(`${rows.length} objectifs ajoutés au planificateur.`);}});}
function reminders(){remember();const rows=records().filter(r=>metadata(r).due&&!metadata(r).archived),all=Store.allTasks(),newTasks=rows.filter(r=>!all.some(t=>t.favoriteReminder===`${favoriteKey(r)}:${metadata(r).due}`)).map(r=>({id:crypto.randomUUID(),game:r.game,title:`Revoir ${r.name}`,due:metadata(r).due,done:false,durationMinutes:15,priority:'Normale',source:'favorites-studio',favoriteReminder:`${favoriteKey(r)}:${metadata(r).due}`,notes:metadata(r).notes}));Store.applyTaskChanges(newTasks);context.toast?.(`${newTasks.length} rappel(s) créé(s), sans doublon.`);change(d=>{d.activity.push({at:Date.now(),label:`${newTasks.length} rappels envoyés au planificateur`});},'',false);}
function teamDialog(team=null,game=context.game){
 const saved=data().draft,draft=team?{...team,members:Array.from({length:4},(_,i)=>({...team.members?.[i],character:String(team.members?.[i]?.character||''),weapon:String(team.members?.[i]?.weapon||''),set:String(team.members?.[i]?.set||'')}))}:saved.game===game?saved:{name:'Mon équipe',members:Array.from({length:4},()=>({character:'',weapon:'',set:''}))};draft.game=game;draft.rotation=normalizeRotation(draft.rotation);
 const catalog=()=>context.catalog||[],lookup=(category,id)=>catalog().find(r=>r.game===game&&r.category===category&&String(r.rawId||r.id)===String(id));
 const saveDraft=()=>{const d=data();d.draft=structuredClone(draft);save(d);};
 const rows=()=>draft.members.map((m,i)=>`<section class="fs-compose-slot"><span class="ws-kicker">PLACE ${i+1}</span>${[['character','character'],['weapon','weapon'],['artifact','set']].map(([category,field])=>{const r=lookup(category,m[field]);return `<button type="button" data-fs-picker="${i}:${field}:${category}">${r?media(r):'<span class="fs-slot-plus">+</span>'}<span>${E(r?.name||({character:'Personnage',weapon:'Arme',artifact:'Set'})[category])}</span></button>`;}).join('')}<button type="button" data-fs-clear-slot="${i}">Vider la place</button></section>`).join('');
 const d=workspaceDialog({title:team?'Modifier l’équipe':'Composer une équipe',wide:true,body:`<label>Nom de l’équipe<input name="name" value="${E(draft.name)}" required maxlength="100"></label><p>Le brouillon est enregistré automatiquement. Chaque membre dispose d’une arme et d’un set.</p><div class="fs-compose-grid" data-fs-compose-rows>${rows()}</div><section data-fs-picker-panel hidden><header><strong data-fs-picker-title>Choisir</strong><button type="button" data-fs-picker-close>Fermer la sélection</button></header><input type="search" data-fs-picker-query placeholder="Rechercher par nom…" aria-label="Rechercher un équipement ou personnage"><div class="fs-picker-grid" data-fs-picker-results></div></section><p class="ws-muted" data-fs-ready></p><details class="fs-rotation-editor"><summary>Construire une rotation</summary><p>Ajoute les actions, leur durée et tes repères. La chronologie est enregistrée avec l’équipe.</p><div data-fs-rotation-rows></div><button type="button" data-fs-rotation-add>+ Ajouter une action</button><button type="button" data-fs-rotation-export>Exporter la rotation CSV</button><output data-fs-rotation-total></output></details>`,submit:'Enregistrer l’équipe favorite',onSubmit:f=>{draft.name=f.get('name').trim();const ready=teamReadiness(draft,catalog());if(new Set(draft.members.filter(m=>m.character).map(m=>m.character)).size!==ready.filled)throw Error('Choisis quatre personnages différents.');if(!ready.filled)throw Error('Choisis au moins un personnage.');if(!draft.name)throw Error('Donne un nom à cette équipe.');remember();Store.saveTeam(game,{...team,id:team?.id||crypto.randomUUID(),name:draft.name,members:structuredClone(draft.members),favorite:true,rotation:normalizeRotation(draft.rotation),updated:Date.now()});saveDraft();change(x=>{x.activity.push({at:Date.now(),label:`Équipe enregistrée : ${draft.name}`});},'',false);}});
 const renderRotation=()=>{const timeline=rotationTimeline(draft.rotation);d.querySelector('[data-fs-rotation-rows]').innerHTML=timeline.map((r,i)=>`<div class="fs-rotation-row"><span>${r.start.toFixed(1)} s</span><select data-rotation-field="slot" data-index="${i}" aria-label="Personnage de l’action ${i+1}">${draft.members.map((m,n)=>`<option value="${n}" ${n===r.slot?'selected':''}>${E(lookup('character',m.character)?.name||`Place ${n+1}`)}</option>`).join('')}</select><select data-rotation-field="action" data-index="${i}" aria-label="Action ${i+1}">${ROTATION_ACTIONS.map(([id,label])=>`<option value="${id}" ${r.action===id?'selected':''}>${label}</option>`).join('')}</select><input type="number" min=".1" max="120" step=".1" value="${r.seconds}" data-rotation-field="seconds" data-index="${i}" aria-label="Durée de l’action ${i+1}"><input type="text" maxlength="200" value="${E(r.note)}" data-rotation-field="note" data-index="${i}" placeholder="Repère…" aria-label="Note de l’action ${i+1}"><button type="button" data-rotation-up="${i}" aria-label="Monter l’action ${i+1}" ${i===0?'disabled':''}>↑</button><button type="button" data-rotation-delete="${i}" aria-label="Supprimer l’action ${i+1}">×</button></div>`).join('');d.querySelector('[data-fs-rotation-total]').textContent=`${timeline.length} actions · ${(timeline.at(-1)?.end||0).toFixed(1)} secondes`;};
 d.addEventListener('change',e=>{const input=e.target;if(!input.dataset.rotationField)return;const index=Number(input.dataset.index);draft.rotation[index][input.dataset.rotationField]=['slot','seconds'].includes(input.dataset.rotationField)?Number(input.value):input.value;draft.rotation=normalizeRotation(draft.rotation);saveDraft();renderRotation();});
 d.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-fs-rotation-add')){draft.rotation.push({slot:0,action:'skill',seconds:1.5,note:''});saveDraft();renderRotation();}if(b.hasAttribute('data-rotation-delete')){draft.rotation.splice(Number(b.dataset.rotationDelete),1);saveDraft();renderRotation();}if(b.hasAttribute('data-rotation-up')){const i=Number(b.dataset.rotationUp);if(i>0)[draft.rotation[i-1],draft.rotation[i]]=[draft.rotation[i],draft.rotation[i-1]];saveDraft();renderRotation();}if(b.hasAttribute('data-fs-rotation-export'))downloadFile('rotation-astralis.csv',csvText([['Début (s)','Fin (s)','Personnage','Action','Repère'],...rotationTimeline(draft.rotation).map(r=>[r.start,r.end,lookup('character',draft.members[r.slot].character)?.name||'',ROTATION_ACTIONS.find(([id])=>id===r.action)?.[1],r.note])]),'text/csv');});renderRotation();
 let picker;const showReadiness=()=>{const r=teamReadiness(draft,catalog());d.querySelector('[data-fs-ready]').textContent=`${r.filled}/4 personnages · ${r.totalGear}/8 équipements${r.complete?' · Équipe complète':` · ${r.missing.join(' ; ')}`}`;};
 const renderResults=()=>{if(!picker)return;const query=d.querySelector('[data-fs-picker-query]').value.toLocaleLowerCase('fr');const desired=picker.category==='weapon'?lookup('character',draft.members[picker.slot].character)?.weapon:'',compatible=Boolean(desired&&catalog().some(r=>r.game===game&&r.category==='weapon'&&r.facet===desired));const rows=catalog().filter(r=>r.game===game&&r.category===picker.category&&(!compatible||r.facet===desired)&&r.name.toLocaleLowerCase('fr').includes(query));d.querySelector('[data-fs-picker-results]').innerHTML=rows.slice(0,64).map(r=>`<button type="button" data-fs-pick="${E(String(r.rawId||r.id))}">${media(r)}<span>${E(r.name)}</span><small>${E(r.facet||'')}</small></button>`).join('')||'<p>Aucun résultat. Essaie un autre nom.</p>';};
 d.addEventListener('input',e=>{if(e.target.name==='name'){draft.name=e.target.value;saveDraft();}if(e.target.matches('[data-fs-picker-query]'))renderResults();});d.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.fsPicker){const [slot,field,category]=t.dataset.fsPicker.split(':');picker={slot:Number(slot),field,category};d.querySelector('[data-fs-picker-panel]').hidden=false;d.querySelector('[data-fs-picker-title]').textContent=`Place ${Number(slot)+1} · ${cats[category]}`;d.querySelector('[data-fs-picker-query]').value='';renderResults();d.querySelector('[data-fs-picker-query]').focus();}if(t.dataset.fsPick){draft.members[picker.slot][picker.field]=t.dataset.fsPick;if(picker.field==='character'){const m=draft.members[picker.slot],desired=lookup('character',m.character)?.weapon,equipped=lookup('weapon',m.weapon),known=desired&&catalog().some(r=>r.game===game&&r.category==='weapon'&&r.facet===desired);if(known&&equipped&&equipped.facet!==desired){m.weapon='';context.toast?.('Choisis une arme compatible avec ce personnage.');}}saveDraft();d.querySelector('[data-fs-compose-rows]').innerHTML=rows();showReadiness();renderRotation();d.querySelector('[data-fs-picker-panel]').hidden=true;}if(t.hasAttribute('data-fs-clear-slot')){draft.members[Number(t.dataset.fsClearSlot)]={character:'',weapon:'',set:''};saveDraft();d.querySelector('[data-fs-compose-rows]').innerHTML=rows();showReadiness();renderRotation();}if(t.hasAttribute('data-fs-picker-close'))d.querySelector('[data-fs-picker-panel]').hidden=true;});showReadiness();saveDraft();
}
function teamProject(team,game){const catalog=context.catalog||[],list=(team.members||[]).map(m=>catalog.find(r=>r.game===game&&r.category==='character'&&String(r.rawId||r.id)===String(m.character))).filter(Boolean).map(r=>{const m=team.members.find(m=>String(m.character)===String(r.rawId||r.id)),gear=[['weapon',m.weapon],['artifact',m.set]].map(([category,id])=>catalog.find(x=>x.game===game&&x.category===category&&String(x.rawId||x.id)===String(id))).filter(Boolean);return {...r,key:favoriteKey(r),preparationSteps:gear.map(x=>({id:crypto.randomUUID(),title:`Préparer ${x.name}`,done:!!x.owned})),rotationNote:rotationTimeline(team.rotation).map(step=>`${step.start}s · ${catalog.find(x=>x.game===game&&x.category==='character'&&String(x.rawId)===String(team.members[step.slot]?.character))?.name||'Personnage'} · ${ROTATION_ACTIONS.find(([id])=>id===step.action)?.[1]}`).join('\n')};});projectDialog(list);}
function exportHTML(list){const doc=`<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ma collection Astralis</title><style>body{font:15px/1.7 system-ui;background:#101720;color:#e4eaf4;margin:40px auto;padding:0 24px;max-width:1100px}h1{font-size:42px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px}article{border:1px solid #ffffff25;padding:24px;border-radius:18px;background:#1a2431}p{white-space:pre-wrap;color:#c2cedc}small{color:#9db5d6}@media print{body{background:white;color:black}article{background:white;color:black;break-inside:avoid}p{color:#333}}</style><h1>Mes inspirations</h1><p>Collection Astralis · ${new Date().toLocaleDateString('fr-FR')}</p><main>${list.map(r=>`<article><small>${E(games[r.game])} · ${E(cats[r.category])}</small><h2>${E(r.name)}</h2><p>${E(metadata(r).notes||r.description||'')}</p><p>${metadata(r).checklist.map(s=>`${s.done?'✓':'□'} ${E(s.title)}`).join('<br>')}</p><small>${E(metadata(r).tags.join(' · '))}</small></article>`).join('')}</main></html>`;downloadFile('ma-collection-astralis.html',doc,'text/html');}
function toolsDialog(){const list=filterFavoriteRecords(records(),data(),ui),d=workspaceDialog({title:'Garder et partager tes collections',submit:null,body:`<div class="ws-template-list"><button type="button" data-fs-export="json"><strong>Sauvegarde JSON</strong><span>Collections, notes, objectifs et références de favoris</span></button><button type="button" data-fs-export="html"><strong>Carnet autonome à partager</strong><span>Une page HTML lisible et imprimable · sélection visible</span></button><button type="button" data-fs-export="csv"><strong>Tableau CSV</strong><span>Annotations et progression de la sélection visible</span></button><label class="ws-file">Importer des collections<input type="file" data-fs-import accept="application/json,.json"></label></div><p>Les notes privées sont incluses dans tes exports : choisis les fiches visibles avant de partager le carnet.</p>`});d.addEventListener('click',e=>{const type=e.target.closest('[data-fs-export]')?.dataset.fsExport;if(type==='json')downloadFile('astralis-favoris.json',JSON.stringify({format:'astralis-favorites-studio',version:1,data:data(),teams:Object.fromEntries(Object.keys(games).map(g=>[g,Store.teams(g).filter(t=>t.favorite)])),references:records().filter(r=>['character','weapon','artifact','material'].includes(r.category)).map(r=>({key:favoriteKey(r),name:r.name}))},null,2));if(type==='html')exportHTML(list);if(type==='csv')downloadFile('astralis-favoris.csv',csvText([['Nom','Univers','Catégorie','État','Note','Objectif','Acquis','Notes'],...list.map(r=>{const m=metadata(r);return [r.name,games[r.game],cats[r.category],m.stage,m.rating,m.target,m.have,m.notes];})]),'text/csv');});d.addEventListener('change',async e=>{if(!e.target.matches('[data-fs-import]'))return;try{const file=e.target.files[0];if(!file)return;if(file.size>4*1024*1024)throw Error('Fichier limité à 4 Mo.');const imported=validateFavoriteImport(JSON.parse(await file.text()));d.close();workspaceDialog({title:'Vérifier les collections importées',body:`<p>${imported.data.collections.length} collection(s), ${Object.keys(imported.data.items).length} annotation(s), ${imported.references.length} référence(s), ${Object.values(imported.teams).reduce((n,rows)=>n+rows.length,0)} équipe(s). Les données existantes sont conservées ; seules les nouvelles sont ajoutées.</p>`,submit:'Fusionner',onSubmit:()=>{change(d=>{d.collections.push(...imported.data.collections.filter(c=>!d.collections.some(x=>x.id===c.id)));for(const [key,m]of Object.entries(imported.data.items))if(!Object.hasOwn(d.items,key))d.items[key]=m;},'Collections importées.');const favs=Store.favorites();for(const r of imported.references)favs[r.key]=true;localStorage.setItem('astralis:favs',JSON.stringify(favs));for(const game of Object.keys(games))for(const team of imported.teams[game])if(!Store.teams(game).some(t=>t.id===team.id))Store.saveTeam(game,team);sealUndo(true);refresh();}});}catch(error){context.toast?.(error.message);}});}
export function mountFavoritesStudio(root,ctx){
 context=ctx;if(!root||root.dataset.mounted)return;root.dataset.mounted='true';let searchTimer;
 root.addEventListener('input',e=>{const t=e.target;if(t.matches('[data-fs-filter=query]')){clearTimeout(searchTimer);const value=t.value,position=t.selectionStart;searchTimer=setTimeout(()=>{ui.query=value;refresh();const next=document.querySelector('[data-fs-filter=query]');next?.focus();next?.setSelectionRange(position,position);},240);}});
 root.addEventListener('change',e=>{const t=e.target;if(t.dataset.fsGearOwned){const r=(context.catalog||[]).find(r=>favoriteKey(r)===t.dataset.fsGearOwned);if(r){remember();Store.toggleOwned(r.game,r.rawId);change(d=>{d.activity.push({at:Date.now(),label:`Possession actualisée : ${r.name}`});},'',false);}}if(t.dataset.fsFilter){ui[t.dataset.fsFilter]=t.value;ui.limit=48;refresh();}if(t.dataset.fsFlag){ui[t.dataset.fsFlag]=t.checked;refresh();}if(t.dataset.fsSelect){if(t.checked)selection.add(t.dataset.fsSelect);else selection.delete(t.dataset.fsSelect);refresh();}if(t.dataset.fsHave){const r=byKey(t.dataset.fsHave);updateMeta(t.dataset.fsHave,{have:Number(t.value)},`Progression : ${r?.name||''}`);}if(t.dataset.fsCheck){const m=metadata(byKey(t.dataset.fsCheck));updateMeta(t.dataset.fsCheck,{checklist:m.checklist.map(s=>s.id===t.dataset.step?{...s,done:t.checked}:s)},'Étape de carnet mise à jour.');}});
 root.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;try{if(t.dataset.fsView){ui.view=t.dataset.fsView;refresh();return;}if(t.dataset.fsCollection){ui.collection=t.dataset.fsCollection;refresh();return;}if(t.dataset.fsCollectionEdit){collectionEditor(data().collections.find(c=>c.id===t.dataset.fsCollectionEdit));return;}if(t.dataset.fsCollectionCopy){const original=data().collections.find(c=>c.id===t.dataset.fsCollectionCopy),copy={...original,id:crypto.randomUUID(),name:original.name+' · copie'};change(d=>{d.collections.push(copy);if(!copy.smart)Object.values(d.items).forEach(m=>{if(m.collections.includes(original.id))m.collections.push(copy.id);});},`Collection dupliquée : ${original.name}`);return;}if(t.dataset.fsEdit){noteEditor(byKey(t.dataset.fsEdit));return;}if(t.dataset.fsOpen){const r=byKey(t.dataset.fsOpen);change(d=>{d.activity.push({at:Date.now(),label:`Fiche consultée : ${r.name}`});});context.open?.(r);return;}if(t.dataset.fsPin){const r=byKey(t.dataset.fsPin);updateMeta(t.dataset.fsPin,{pinned:!metadata(r).pinned},`Épingle : ${r.name}`);return;}if(t.dataset.fsCompare){const key=t.dataset.fsCompare;if(comparison.includes(key))comparison=comparison.filter(k=>k!==key);else if(comparison.length<4)comparison.push(key);else context.toast?.('Le comparateur contient déjà quatre fiches.');refresh();return;}if(t.dataset.fsMissingPlan){const g=t.dataset.fsGame;planMissing(Store.teams(g).find(x=>x.id===t.dataset.fsMissingPlan),g);return;}if(t.dataset.fsTeamEdit){const g=t.dataset.fsGame;teamDialog(Store.teams(g).find(x=>x.id===t.dataset.fsTeamEdit),g);return;}if(t.dataset.fsTeamProject){const g=t.dataset.fsGame;teamProject(Store.teams(g).find(x=>x.id===t.dataset.fsTeamProject),g);return;}if(t.dataset.fsSavedView){const view=data().views.find(v=>v.id===t.dataset.fsSavedView);ui={...ui,...view.filters};refresh();return;}if(t.dataset.fsDeleteView){change(d=>{d.views=d.views.filter(v=>v.id!==t.dataset.fsDeleteView);},'Vue supprimée.');return;}
 const a=t.dataset.fsAction;if(a==='load-more'){ui.limit=(Number(ui.limit)||48)+48;refresh();}if(a==='collection')collectionEditor();if(a==='team')teamDialog();if(a==='batch')batchDialog();if(a==='project')projectDialog([...selection].map(byKey).filter(Boolean));if(a==='compare')comparisonDialog();if(a==='tools')toolsDialog();if(a==='reminders')reminders();if(a==='select-all'){selection=new Set(filterFavoriteRecords(records(),data(),ui).map(favoriteKey));refresh();}if(a==='clear-selection'){selection.clear();refresh();}if(a==='reset-filters'){ui={...ui,query:'',game:'all',category:'all',tag:'all',collection:'all',archive:false,pinned:false};refresh();}if(a==='dismiss-spotlight'){spotlight='';refresh();}if(a==='discover'){const list=filterFavoriteRecords(records(),data(),ui);spotlight=list[Math.floor(Math.random()*list.length)]?.key||'';refresh();document.querySelector('.fs-spotlight')?.scrollIntoView({behavior:document.documentElement.dataset.studioMotion==='reduced'?'auto':'smooth',block:'center'});}if(a==='saved-view')workspaceDialog({title:'Retrouver cette sélection',body:'<label>Nom de la vue<input name="name" required maxlength="60"></label>',onSubmit:f=>change(d=>{d.views.push({id:crypto.randomUUID(),name:f.get('name').trim(),filters:{...ui}});},'Vue enregistrée.')});if(a==='undo'){const snapshot=undo.pop();if(snapshot){const restored=rollbackWorkspaceValue(Object.fromEntries(Object.entries(snapshot).filter(([k])=>k!=='after')),snapshot.after||snapshot,captureUndo());save(restored.data);localStorage.setItem('astralis:favs',JSON.stringify(restored.favs));for(const [game,teams]of Object.entries(restored.teams))localStorage.setItem(`astralis:teams:${game}`,JSON.stringify(teams));for(const game of Object.keys(games)){localStorage.setItem(`astralis:tasks:${game}`,JSON.stringify(restored.tasks.filter(t=>t.game===game)));localStorage.setItem(`astralis:owned:${game}`,JSON.stringify(restored.owned[game]));}if(restored.planner===null)localStorage.removeItem(PLANNING_KEY);else localStorage.setItem(PLANNING_KEY,JSON.stringify(restored.planner));refresh();context.toast?.('Dernière action annulée.');}}}catch(error){context.toast?.(error.message);}});
 root.addEventListener('dragstart',e=>{const card=e.target.closest('[data-fs-drag]');if(card){e.dataTransfer.setData('text/plain',card.dataset.fsDrag);e.dataTransfer.effectAllowed='move';}});root.addEventListener('dragover',e=>{if(e.target.closest('[data-fs-stage-drop],[data-fs-collection-drop],[data-fs-drag]'))e.preventDefault();});root.addEventListener('drop',e=>{const source=e.dataTransfer.getData('text/plain'),r=byKey(source);if(!r)return;const stage=e.target.closest('[data-fs-stage-drop]'),collection=e.target.closest('[data-fs-collection-drop]'),target=e.target.closest('[data-fs-drag]');if(!stage&&!collection&&!target)return;e.preventDefault();if(stage)updateMeta(source,{stage:stage.dataset.fsStageDrop},`Progression : ${r.name}`);else if(collection){const c=data().collections.find(c=>c.id===collection.dataset.fsCollectionDrop);if(c.smart)return context.toast?.('Cette collection est automatique : adapte les règles ou les étiquettes.');updateMeta(source,{collections:[...new Set([...metadata(r).collections,c.id])]},`Ajout à ${c.name} : ${r.name}`);}else{const list=filterFavoriteRecords(records(),data(),ui).map(favoriteKey),from=list.indexOf(source),to=list.indexOf(target.dataset.fsDrag);if(from<0||to<0||from===to)return;list.splice(from,1);list.splice(to,0,source);change(d=>{list.forEach((key,i)=>{d.items[key]={...normalizeFavoriteMeta(d.items[key]),order:i};});},'Ordre des favoris ajusté.');ui.sort='manual';refresh();}});
}
